# Independent review suffix derived from hash-frozen blind artifacts.
# No author fixture/oracle is used. No filesystem or network access at runtime.
import io as _review_io
import types as _review_types
import unittest as _review_unittest
import json as _review_json
import random as _review_random
_review_api = _review_types.SimpleNamespace(toy_predict=toy_predict,
    probe_report=probe_report, exact_interval_report=exact_interval_report)
_review_reference = {"__name__": "independent_geometric_reference"}
exec('"""Blind independent reference: geometric intersection with exact error sets.\n\nOnly the supplied raw premises were read before this file was frozen.\nThis is deliberately not a breakpoint partition/sampling implementation.\n"""\nfrom fractions import Fraction\n\nA, B = Fraction(5, 4), Fraction(4, 3)\nLIMIT = 1_000_000\nGROUPS = frozenset(("far", "notch-near"))\nKEYS = frozenset(("group", "x", "label", "count"))\n\n\ndef _rational(value, name):\n    if type(value) not in (int, Fraction):\n        raise TypeError(name + " must be a built-in int or exact Fraction")\n    value = Fraction(value)\n    if abs(value.numerator) > LIMIT or value.denominator > LIMIT:\n        raise ValueError(name + " exceeds the public rational-size budget")\n    return value\n\n\ndef _predict_internal(x):\n    # Intermediate exact rationals do not pass through the public input limit.\n    return int(x >= 0 and not (A <= x < B))\n\n\ndef toy_predict(x):\n    x = _rational(x, "x")\n    if not -3 <= x <= 3:\n        raise ValueError("x outside D")\n    return _predict_internal(x)\n\n\ndef _validate(cases, epsilon, model):\n    if model is not toy_predict:\n        raise TypeError("only the literal toy_predict object is supported")\n    epsilon = _rational(epsilon, "epsilon")\n    if not 0 <= epsilon <= 1:\n        raise ValueError("epsilon outside [0,1]")\n    if type(cases) not in (list, tuple):\n        raise TypeError("cases must be a built-in list or tuple")\n    if not 1 <= len(cases) <= 64:\n        raise ValueError("cases length outside [1,64]")\n    normalized = []\n    for row in cases:\n        if type(row) is not dict:\n            raise TypeError("case row must be a built-in dict")\n        if row.keys() != KEYS:\n            raise ValueError("case keys must be exactly group,x,label,count")\n        group, label, count = row["group"], row["label"], row["count"]\n        if type(group) is not str:\n            raise TypeError("group must be a built-in str")\n        if group not in GROUPS:\n            raise ValueError("unknown group")\n        if type(label) is not int:\n            raise TypeError("label must be a built-in int")\n        if label not in (0, 1):\n            raise ValueError("label must be 0 or 1")\n        if type(count) is not int:\n            raise TypeError("count must be a built-in int")\n        if not 1 <= count <= 10_000:\n            raise ValueError("count outside [1,10000]")\n        x = _rational(row["x"], "x")\n        if not -3 <= x <= 3:\n            raise ValueError("x outside D")\n        if label != int(x >= 0):\n            raise ValueError("center label disagrees with g")\n        lower, upper = x - epsilon, x + epsilon\n        if lower < -3 or upper > 3:\n            raise ValueError("complete allowed interval leaves D; no clipping")\n        if (label == 0 and upper >= 0) or (label == 1 and lower < 0):\n            raise ValueError("complete interval is not label preserving")\n        normalized.append((group, x, label, count, lower, upper))\n    return tuple(normalized), epsilon\n\n\ndef _validate_deltas(deltas, epsilon):\n    if type(deltas) not in (list, tuple):\n        raise TypeError("deltas must be a built-in list or tuple")\n    if not 1 <= len(deltas) <= 64:\n        raise ValueError("deltas length outside [1,64]")\n    normalized = tuple(_rational(d, "delta") for d in deltas)\n    if len(set(normalized)) != len(normalized):\n        raise ValueError("repeated numerical probe")\n    if Fraction(0) not in normalized:\n        raise ValueError("probes must include 0")\n    if any(abs(d) > epsilon for d in normalized):\n        raise ValueError("probe outside allowed radius")\n    return normalized\n\n\ndef _new_probe():\n    return dict(cases=0, clean_correct=0, probe_trials=0,\n                probe_correct=0, tested_robust_correct=0)\n\n\ndef _finish_probe(record):\n    record["clean_accuracy"] = Fraction(record["clean_correct"], record["cases"])\n    record["average_accuracy"] = Fraction(record["probe_correct"], record["probe_trials"])\n    record["tested_robust_accuracy"] = Fraction(record["tested_robust_correct"], record["cases"])\n    return record\n\n\ndef probe_report(cases, deltas, epsilon, *, model=toy_predict):\n    normalized, epsilon = _validate(cases, epsilon, model)\n    deltas = _validate_deltas(deltas, epsilon)\n    total, groups = _new_probe(), {}\n    for group, x, label, count, lower, upper in normalized:\n        record = groups.setdefault(group, _new_probe())\n        clean = int(_predict_internal(x) == label)\n        outcomes = tuple(_predict_internal(x + d) == label for d in deltas)\n        for destination in (total, record):\n            destination["cases"] += count\n            destination["clean_correct"] += count * clean\n            destination["probe_trials"] += count * len(deltas)\n            destination["probe_correct"] += count * sum(outcomes)\n            destination["tested_robust_correct"] += count * int(all(outcomes))\n    return {"total": _finish_probe(total),\n            "groups": {g: _finish_probe(r) for g, r in groups.items()}}\n\n\n# Intervals are (lower, upper, lower_is_closed, upper_is_closed).\n# This geometric oracle is independent of point prediction and of any cells,\n# partition probes, floating epsilon, or enumeration of rational inputs.\ndef _intersects(left, right):\n    lo = max(left[0], right[0])\n    hi = min(left[1], right[1])\n    if lo < hi:\n        return True\n    if lo > hi:\n        return False\n    def contains(interval, point):\n        a, b, ac, bc = interval\n        return ((a < point < b) or\n                (point == a and ac and (a < b or bc)) or\n                (point == b and bc and (a < b or ac)))\n    return contains(left, lo) and contains(right, lo)\n\n\ndef error_set(label):\n    if label == 1:\n        return ((Fraction(-3), Fraction(0), True, False),\n                (A, B, True, False))\n    return ((Fraction(0), A, True, False),\n            (B, Fraction(3), True, True))\n\n\ndef geometric_correct(lower, upper, label):\n    allowed = (lower, upper, True, True)\n    return not any(_intersects(allowed, wrong) for wrong in error_set(label))\n\n\ndef exact_interval_report(cases, epsilon, *, model=toy_predict):\n    normalized, epsilon = _validate(cases, epsilon, model)\n    total, groups = dict(cases=0, robust_correct=0), {}\n    for group, x, label, count, lower, upper in normalized:\n        record = groups.setdefault(group, dict(cases=0, robust_correct=0))\n        correct = int(geometric_correct(lower, upper, label))\n        for destination in (total, record):\n            destination["cases"] += count\n            destination["robust_correct"] += count * correct\n    for record in (total, *groups.values()):\n        record["robust_accuracy"] = Fraction(record["robust_correct"], record["cases"])\n    return {"total": total, "groups": groups}\n', _review_reference)
_review_tests = {"__name__": "independent_blind_tests", "r": _review_api}
exec('"""Bounded independent stdlib checks. Finite evidence, not a real-domain proof."""\nimport copy\nfrom fractions import Fraction as F\nimport unittest\n\n\n\ndef case(x, label=1, count=1, group="notch-near"):\n    return dict(group=group, x=x, label=label, count=count)\n\n\nMAIN = [case(-2, 0, 9, "far"), case(2, 1, 9, "far"), case(1, 1, 2)]\nMIXED = [case(-2, 0, 1, "far"), case(2, 1, 1, "far"), case(1, 1, 18)]\nP3 = [F(-1, 2), 0, F(1, 2)]\nP4 = [F(-1, 2), 0, F(3, 10), F(1, 2)]\n\n\ndef record(n, clean, trials, right, robust):\n    return dict(cases=n, clean_correct=clean, clean_accuracy=F(clean, n),\n                probe_trials=trials, probe_correct=right,\n                average_accuracy=F(right, trials),\n                tested_robust_correct=robust, tested_robust_accuracy=F(robust, n))\n\n\ndef exact_record(n, correct):\n    return dict(cases=n, robust_correct=correct, robust_accuracy=F(correct, n))\n\n\ndef safe_radius_oracle(x, label, epsilon):\n    """Independent inequality solution, not interval-intersection code."""\n    if label == 0:\n        return True\n    if x < F(5, 4):\n        return epsilon < F(5, 4) - x\n    if x < F(4, 3):\n        return False\n    return epsilon <= x - F(4, 3)\n\n\nclass IntChild(int):\n    pass\n\n\nclass FractionChild(F):\n    pass\n\n\nclass ListChild(list):\n    pass\n\n\nclass DictChild(dict):\n    pass\n\n\nclass StrChild(str):\n    pass\n\n\nclass TupleChild(tuple):\n    pass\n\n\nclass Tests(unittest.TestCase):\n    def assert_rejected(self, fn, *args, **kwargs):\n        snapshot = copy.deepcopy((args, kwargs))\n        with self.assertRaises((ValueError, TypeError)):\n            fn(*args, **kwargs)\n        self.assertEqual((args, kwargs), snapshot)\n\n    def test_main_p3(self):\n        self.assertEqual(r.probe_report(MAIN, P3, F(1, 2)), {\n            "total": record(20, 20, 60, 60, 20),\n            "groups": {"far": record(18, 18, 54, 54, 18),\n                       "notch-near": record(2, 2, 6, 6, 2)}})\n\n    def test_main_p4(self):\n        self.assertEqual(r.probe_report(MAIN, P4, F(1, 2)), {\n            "total": record(20, 20, 80, 78, 18),\n            "groups": {"far": record(18, 18, 72, 72, 18),\n                       "notch-near": record(2, 2, 8, 6, 0)}})\n\n    def test_main_exact(self):\n        self.assertEqual(r.exact_interval_report(MAIN, F(1, 2)), {\n            "total": exact_record(20, 18),\n            "groups": {"far": exact_record(18, 18),\n                       "notch-near": exact_record(2, 0)}})\n\n    def test_mixture(self):\n        self.assertEqual(r.probe_report(MIXED, P4, F(1, 2)), {\n            "total": record(20, 20, 80, 62, 2),\n            "groups": {"far": record(2, 2, 8, 8, 2),\n                       "notch-near": record(18, 18, 72, 54, 0)}})\n        self.assertEqual(r.exact_interval_report(MIXED, F(1, 2)), {\n            "total": exact_record(20, 2),\n            "groups": {"far": exact_record(2, 2),\n                       "notch-near": exact_record(18, 0)}})\n        for workload in (MAIN, MIXED):\n            p = r.probe_report(workload, P4, F(1, 2))\n            e = r.exact_interval_report(workload, F(1, 2))\n            self.assertEqual(sum(g["average_accuracy"] for g in p["groups"].values()) / 2, F(7, 8))\n            self.assertEqual(sum(g["robust_accuracy"] for g in e["groups"].values()) / 2, F(1, 2))\n\n    def test_point_endpoints(self):\n        for x, expected in ((-3, 0), (0, 1), (F(5, 4), 0), (F(4, 3), 1), (3, 1),\n                            (F(1249, 1000), 1), (F(1251, 1000), 0),\n                            (F(1333, 1000), 0), (F(1334, 1000), 1)):\n            self.assertEqual(r.toy_predict(x), expected)\n\n    def test_interval_endpoints(self):\n        for lo, hi, expected in ((F(1), F(5, 4), 0), (F(4, 3), F(3, 2), 1),\n                                 (F(5, 4), F(4, 3), 0),\n                                 (F(5, 4), F(5, 4), 0),\n                                 (F(4, 3), F(4, 3), 1)):\n            report = r.exact_interval_report([case((lo + hi) / 2)], (hi - lo) / 2)\n            self.assertEqual(report["total"]["robust_accuracy"], F(expected))\n\n    def test_stable_wrong_zero_radius(self):\n        cases = [case(F(13, 10))]\n        self.assertEqual(r.probe_report(cases, [0], 0)["total"], record(1, 0, 1, 0, 0))\n        self.assertEqual(r.exact_interval_report(cases, 0)["total"], exact_record(1, 0))\n\n    def test_zero_radius_identity(self):\n        for x in (F(-3), F(-1, 7), F(0), F(1), F(5, 4), F(13, 10), F(4, 3), F(3)):\n            label = int(x >= 0)\n            p = r.probe_report([case(x, label)], [0], 0)["total"]\n            e = r.exact_interval_report([case(x, label)], 0)["total"]\n            self.assertEqual(p["clean_accuracy"], p["average_accuracy"])\n            self.assertEqual(p["clean_accuracy"], p["tested_robust_accuracy"])\n            self.assertEqual(p["clean_accuracy"], e["robust_accuracy"])\n\n    def test_label_boundary_and_no_clipping(self):\n        self.assert_rejected(r.exact_interval_report, [case(F(1, 4))], F(1, 2))\n        self.assert_rejected(r.exact_interval_report, [case(F(-1, 4), 0)], F(1, 4))\n        self.assertEqual(r.exact_interval_report([case(F(1, 4))], F(1, 4))["total"], exact_record(1, 1))\n        self.assert_rejected(r.probe_report, [case(3)], [0], F(1, 2))\n        self.assert_rejected(r.exact_interval_report, [case(3)], F(1, 2))\n        self.assert_rejected(r.exact_interval_report, [case(3)], F(1, 2), clip=True)\n        self.assert_rejected(r.probe_report, MAIN, P3, F(1, 2), clip=False)\n\n    def test_quantifiers(self):\n        xs, ds = (F(11, 10), F(3, 2)), (F(-1, 4), F(0), F(1, 5))\n        matrix = [[r.toy_predict(x + d) == 1 for d in ds] for x in xs]\n        self.assertEqual(matrix, [[True, True, False], [False, True, True]])\n        self.assertEqual(F(sum(all(row) for row in matrix), 2), 0)\n        self.assertEqual(min(F(sum(row[j] for row in matrix), 2) for j in range(3)), F(1, 2))\n        self.assertEqual(r.exact_interval_report([case(x) for x in xs], F(1, 4))["total"], exact_record(2, 0))\n        # Independent interval arithmetic: shared-error intervals are disjoint.\n        a_error = (F(5, 4) - xs[0], F(4, 3) - xs[0])\n        b_error = (F(5, 4) - xs[1], F(4, 3) - xs[1])\n        self.assertEqual(a_error, (F(3, 20), F(7, 30)))\n        self.assertEqual(b_error, (F(-1, 4), F(-1, 6)))\n        self.assertLess(b_error[1], a_error[0])\n\n    def test_independent_grid_and_monotonicity(self):\n        valid_count = 0\n        for k in range(-36, 37):\n            x, label = F(k, 12), int(k >= 0)\n            previous = 1\n            for j in range(13):\n                epsilon = F(j, 12)\n                lo, hi = x - epsilon, x + epsilon\n                valid = lo >= -3 and hi <= 3 and (hi < 0 if label == 0 else lo >= 0)\n                if not valid:\n                    self.assert_rejected(r.exact_interval_report, [case(x, label)], epsilon)\n                    continue\n                valid_count += 1\n                actual = r.exact_interval_report([case(x, label)], epsilon)["total"]["robust_accuracy"]\n                self.assertEqual(actual, F(safe_radius_oracle(x, label, epsilon)))\n                self.assertLessEqual(actual, previous)\n                previous = actual\n                ds = [0] if epsilon == 0 else [-epsilon, 0, epsilon]\n                p = r.probe_report([case(x, label)], ds, epsilon)["total"]\n                self.assertLessEqual(actual, p["tested_robust_accuracy"])\n                self.assertLessEqual(p["tested_robust_accuracy"], p["clean_accuracy"])\n                self.assertLessEqual(p["tested_robust_accuracy"], p["average_accuracy"])\n        self.assertGreater(valid_count, 500)\n\n    def test_moving_probes_not_monotonic(self):\n        small = r.probe_report([case(1)], [-F(3, 10), 0, F(3, 10)], F(3, 10))\n        large = r.probe_report([case(1)], P3, F(1, 2))\n        self.assertEqual(small["total"]["tested_robust_accuracy"], 0)\n        self.assertEqual(large["total"]["tested_robust_accuracy"], 1)\n        self.assertEqual(r.exact_interval_report([case(1)], F(1, 2))["total"]["robust_accuracy"], 0)\n\n    def test_nested_probes(self):\n        small = r.probe_report(MAIN, P3, F(1, 2))\n        large = r.probe_report(MAIN, P4, F(1, 2))\n        self.assertLessEqual(large["total"]["tested_robust_accuracy"], small["total"]["tested_robust_accuracy"])\n\n    def test_reordering_splitting_and_repetition(self):\n        for fn, args in ((r.probe_report, (P4, F(1, 2))), (r.exact_interval_report, (F(1, 2),))):\n            original = fn(MAIN, *args)\n            self.assertEqual(fn(list(reversed(MAIN)), *args), original)\n            split = [case(-2, 0, 4, "far"), case(-2, 0, 5, "far"), *MAIN[1:]]\n            self.assertEqual(fn(split, *args), original)\n            for duplicated in (MAIN + MAIN, [dict(row, count=2 * row["count"]) for row in MAIN]):\n                doubled = fn(duplicated, *args)\n                for scope, before, after in (("total", original["total"], doubled["total"]),\n                        *((g, original["groups"][g], doubled["groups"][g]) for g in original["groups"])):\n                    for key, value in before.items():\n                        self.assertEqual(after[key], value if type(value) is F else 2 * value)\n\n    def test_one_group_and_exact_types(self):\n        for fn, args in ((r.probe_report, ([0], 0)), (r.exact_interval_report, (0,))):\n            output = fn([case(1)], *args)\n            self.assertEqual(set(output["groups"]), {"notch-near"})\n            for rec in (output["total"], *output["groups"].values()):\n                for key, value in rec.items():\n                    self.assertIs(type(value), F if key.endswith("accuracy") else int)\n\n    def test_input_nonmutation(self):\n        for fn, args in ((r.probe_report, (P4, F(1, 2))), (r.exact_interval_report, (F(1, 2),))):\n            workload = copy.deepcopy(MAIN)\n            before = copy.deepcopy((workload, args))\n            fn(workload, *args)\n            self.assertEqual((workload, args), before)\n        invalid = MAIN + [case(F(1, 4))]\n        self.assert_rejected(r.probe_report, invalid, P4, F(1, 2))\n        self.assert_rejected(r.probe_report, MAIN, [0, F(1, 3), True], F(1, 2))\n\n    def test_model_identity(self):\n        def should_not_be_called(x):\n            raise AssertionError("unsupported model was executed")\n        for model in (should_not_be_called, lambda x: r.toy_predict(x), None, object(), 1):\n            with self.assertRaises((ValueError, TypeError)):\n                r.exact_interval_report(MAIN, F(1, 2), model=model)\n            with self.assertRaises((ValueError, TypeError)):\n                r.probe_report(MAIN, P3, F(1, 2), model=model)\n\n    def test_numeric_type_rejections(self):\n        bad = (True, False, 1.0, "1", IntChild(1), FractionChild(1, 2), complex(1))\n        for value in bad:\n            self.assert_rejected(r.toy_predict, value)\n            self.assert_rejected(r.exact_interval_report, [case(value)], 0)\n            self.assert_rejected(r.exact_interval_report, [case(1)], value)\n            self.assert_rejected(r.probe_report, [case(1)], [0, value], F(1, 2))\n\n    def test_rational_budgets_and_intermediates(self):\n        for value in (1_000_001, F(1, 1_000_001), F(1_000_001, 1_000_000)):\n            self.assert_rejected(r.toy_predict, value)\n            self.assert_rejected(r.exact_interval_report, [case(value)], 0)\n        self.assert_rejected(r.exact_interval_report, [case(1)], F(1, 1_000_001))\n        self.assert_rejected(r.probe_report, [case(1)], [0, F(1, 1_000_001)], F(1, 2))\n        self.assertEqual(r.toy_predict(F(2_000_000, 2_000_000)), 1)\n        x, epsilon = F(999_983, 500_000), F(1, 999_983)\n        self.assertGreater((x + epsilon).denominator, 1_000_000)\n        self.assertEqual(r.probe_report([case(x)], [0, epsilon], epsilon)["total"], record(1, 1, 2, 2, 1))\n        self.assertEqual(r.exact_interval_report([case(x)], epsilon)["total"], exact_record(1, 1))\n\n    def test_shape_rejections(self):\n        for value in ([], (), {}, ListChild([case(1)]), TupleChild((case(1),)), [case(1)] * 65,\n                      [DictChild(case(1))], [tuple(case(1).items())]):\n            self.assert_rejected(r.exact_interval_report, value, 0)\n        with self.assertRaises((TypeError, ValueError)):\n            r.exact_interval_report(iter([case(1)]), 0)\n        for row in (dict(case(1), extra=1), {k: v for k, v in case(1).items() if k != "count"}):\n            self.assert_rejected(r.exact_interval_report, [row], 0)\n\n    def test_values_and_domain_rejections(self):\n        for key, values in (("group", ("unknown", True, StrChild("far"))),\n                            ("label", (True, 2, 1.0, IntChild(1), "1")),\n                            ("count", (True, 0, -1, 10_001, 1.0, IntChild(1), "1"))):\n            for value in values:\n                self.assert_rejected(r.exact_interval_report, [dict(case(1), **{key: value})], 0)\n        self.assert_rejected(r.exact_interval_report, [case(1, 0)], 0)\n        for epsilon in (-1, F(-1, 100), F(1001, 1000), 2):\n            self.assert_rejected(r.exact_interval_report, [case(1)], epsilon)\n        for x in (-4, 4):\n            self.assert_rejected(r.toy_predict, x)\n            self.assert_rejected(r.exact_interval_report, [case(x, int(x >= 0))], 0)\n        self.assert_rejected(r.exact_interval_report, [case(-3, 0)], F(1, 100))\n\n    def test_probe_rejections(self):\n        for ds in ([], (), {}, ListChild([0]), TupleChild((0,)), [F(1, 10)],\n                   [0, 0], [0, F(0, 1)], [0, F(1, 2), F(2, 4)],\n                   [0, F(501, 1000)], [F(i, 1000) for i in range(65)]):\n            self.assert_rejected(r.probe_report, [case(1)], ds, F(1, 2))\n        with self.assertRaises((TypeError, ValueError)):\n            r.probe_report([case(1)], iter([0]), F(1, 2))\n\n    def test_tuple_and_budget_edges(self):\n        self.assertEqual(r.probe_report(tuple(MAIN), tuple(P4), F(1, 2)), r.probe_report(MAIN, P4, F(1, 2)))\n        cases = [case(2, count=10_000)] * 64\n        ds = [F(i, 1000) for i in range(64)]\n        self.assertEqual(r.probe_report(cases, ds, F(1, 2))["total"], record(640_000, 640_000, 40_960_000, 40_960_000, 640_000))\n        self.assertEqual(r.toy_predict(F(1, 1_000_000)), 1)\n        self.assertEqual(r.toy_predict(F(1_000_000, 999_999)), 1)\n\n\n', _review_tests)
_review_suite = _review_unittest.defaultTestLoader.loadTestsFromTestCase(_review_tests["Tests"])
_review_buffer = _review_io.StringIO()
_review_result = _review_unittest.TextTestRunner(stream=_review_buffer, verbosity=1).run(_review_suite)
assert _review_result.wasSuccessful(), _review_buffer.getvalue()
_review_rng = _review_random.Random(20261005)
_review_F = _review_tests["F"]
_review_differentials = 0
for _review_round in range(500):
    _review_e = _review_rng.choice([_review_F(0), _review_F(1,100), _review_F(1,10),
                                  _review_F(1,4), _review_F(1,2), _review_F(1)])
    _review_pool = [_review_F(k,120) for k in range(-360,361)
        if _review_F(k,120)-_review_e >= -3 and _review_F(k,120)+_review_e <= 3
        and (_review_F(k,120)+_review_e < 0 or _review_F(k,120)-_review_e >= 0)]
    _review_rows = []
    for _review_i in range(_review_rng.randrange(1,5)):
        _review_x = _review_rng.choice(_review_pool)
        _review_rows.append(dict(group="far" if _review_i%2 else "notch-near",
            x=_review_x, label=int(_review_x>=0), count=_review_rng.randrange(1,10001)))
    _review_ds = [0] if _review_e == 0 else [-_review_e, -_review_e/2, 0, _review_e/2, _review_e]
    assert probe_report(_review_rows, _review_ds, _review_e) == _review_reference["probe_report"](_review_rows, _review_ds, _review_e)
    assert exact_interval_report(_review_rows, _review_e) == _review_reference["exact_interval_report"](_review_rows, _review_e)
    _review_differentials += 2
print(_review_json.dumps({"independentBlindTests": _review_result.testsRun,
    "independentDifferentialReports": _review_differentials,
    "reviewStatus": "needs-independent-review", "expertReview": False}, sort_keys=True))
